import {
  Button,
  Card,
  CardHeader,
  CardBody,
  FormGroup,
  Form,
  Input,
  Container,
  Row,
  Col,
  Label,
  Progress,
  Alert,
} from "reactstrap";
import { useState } from "react";
import { db, auth } from "../../firebase";  // Ensure correct import path
import { collection, addDoc } from "firebase/firestore";

const CarbonDataInput = () => {
  const [carbonData, setCarbonData] = useState({
    date: "",
    category: "",
    value: "",
    unit: "",
    carbonEmission: 0,
  });
  const [impactLevel, setImpactLevel] = useState("Low");
  const [submitted, setSubmitted] = useState(false);

  // Handle input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    const updatedData = { ...carbonData, [name]: value };

    if (name === "value" || name === "category") {
      const calculatedEmission = calculateCarbonEmissions(updatedData.category, parseFloat(value) || 0);
      updatedData.carbonEmission = calculatedEmission;
      setImpactLevel(getImpactLevel(calculatedEmission));
    }

    setCarbonData(updatedData);
  };

  // Calculate carbon emissions based on category
  const calculateCarbonEmissions = (category, value) => {
    switch (category) {
      case "Transport":
        return value * 2.31; // Example: 2.31 kg CO2 per liter of petrol
      case "Electricity":
        return value * 0.92; // Example: 0.92 kg CO2 per kWh
      case "Diet":
        return value * 3.5; // Example: 3.5 kg CO2 per kg of beef
      case "Waste":
        return value * 0.75; // Example: 0.75 kg CO2 per kg of waste
      default:
        return 0;
    }
  };

  // Determine impact level based on emission value
  const getImpactLevel = (emission) => {
    if (emission <= 10) return "Low";
    if (emission > 10 && emission <= 50) return "Moderate";
    return "High";
  };

  // Get valid units dynamically based on category selection
  const getValidUnits = (category) => {
    switch (category) {
      case "Transport":
        return ["liters", "kg"];
      case "Electricity":
        return ["kWh"];
      case "Diet":
        return ["kg"];
      case "Waste":
        return ["kg"];
      default:
        return [];
    }
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!auth.currentUser) {
      alert("Please log in to save your data.");
      return;
    }

    try {
      await addDoc(collection(db, "carbon_logs"), {
        userId: auth.currentUser.uid,
        date: carbonData.date,
        category: carbonData.category,
        value: carbonData.value,
        unit: carbonData.unit,
        carbonEmission: carbonData.carbonEmission,
      });

      setSubmitted(true);
      setTimeout(() => setSubmitted(false), 3000); // Reset UI after saving
      setCarbonData({ date: "", category: "", value: "", unit: "", carbonEmission: 0 });
    } catch (error) {
      console.error("Error saving data:", error);
      alert("Failed to save data. Please try again.");
    }
  };

  return (
    <Container className="mt-5" fluid>
      <Row className="justify-content-center">
        <Col lg="8">
          <Card className="bg-dark text-white shadow-lg">
            <CardHeader className="bg-gradient-info text-center">
              <h3 className="mb-0 text-white">
                <i className="fas fa-leaf"></i> Carbon Data Input
              </h3>
            </CardHeader>
            <CardBody>
              <Form>
                <Row>
                  <Col md="6">
                    <FormGroup>
                      <Label>Date</Label>
                      <Input
                        type="date"
                        name="date"
                        value={carbonData.date}
                        onChange={handleChange}
                        required
                      />
                    </FormGroup>
                  </Col>
                  <Col md="6">
                    <FormGroup>
                      <Label>Activity Category</Label>
                      <Input
                        type="select"
                        name="category"
                        value={carbonData.category}
                        onChange={handleChange}
                        required
                      >
                        <option value="">Select Category</option>
                        <option value="Transport">🚗 Transport</option>
                        <option value="Electricity">⚡ Electricity</option>
                        <option value="Diet">🥩 Diet</option>
                        <option value="Waste">🗑 Waste Management</option>
                      </Input>
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col md="6">
                    <FormGroup>
                      <Label>Value</Label>
                      <Input
                        type="number"
                        name="value"
                        value={carbonData.value}
                        onChange={handleChange}
                        required
                      />
                    </FormGroup>
                  </Col>
                  <Col md="6">
                    <FormGroup>
                      <Label>Unit</Label>
                      <Input
                        type="select"
                        name="unit"
                        value={carbonData.unit}
                        onChange={handleChange}
                        disabled={!carbonData.category}
                        required
                      >
                        <option value="">Select Unit</option>
                        {getValidUnits(carbonData.category).map((unit) => (
                          <option key={unit} value={unit}>{unit}</option>
                        ))}
                      </Input>
                    </FormGroup>
                  </Col>
                </Row>

                {/* Live Carbon Emission Result */}
                <Row>
                  <Col md="12" className="text-center mt-3">
                    <h4>
                      Estimated CO₂ Emission:{" "}
                      <span className="text-warning">{carbonData.carbonEmission.toFixed(2)} kg</span>
                    </h4>
                    <Progress
                      color={impactLevel === "Low" ? "success" : impactLevel === "Moderate" ? "warning" : "danger"}
                      value={(carbonData.carbonEmission / 100) * 100}
                    />
                    <p className={`mt-2 text-${impactLevel === "Low" ? "success" : impactLevel === "Moderate" ? "warning" : "danger"}`}>
                      Impact Level: {impactLevel}
                    </p>
                  </Col>
                </Row>

                {/* Submit Button */}
                <Row className="text-center mt-4">
                  <Col>
                    <Button color="success" size="lg" className="px-5 shadow-lg" type="submit" onClick={handleSubmit}>
                      <i className="fas fa-save"></i> Save Data
                    </Button>
                  </Col>
                </Row>
              </Form>

              {/* Success Message */}
              {submitted && <Alert color="success" className="text-center mt-3">✅ Data saved successfully!</Alert>}
            </CardBody>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default CarbonDataInput;
